"""Write references, checked-source ledger, and problem entries for this shard."""
from pathlib import Path
import json,re,csv
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[1]
items=json.loads((OUT/'items.json').read_text())

problems=[
 dict(id='GP-1985-20',title='Deciding identities in all finite-dimensional subspace lattices',
 statement=r'''For a fixed field \(F\), is there an algorithm deciding whether two finite terms in sum and intersection have equal values on every tuple of subspaces in every finite-dimensional \(F\)-vector space? The concrete proposed reduction is to dimension \(1+\min\{\max(d(p),d(q)),\max(k(p),k(q))\}\), where \(d\) and \(k\) count joins and meets in the written terms.''',
 occurrences=['1985-653.2','1985-653.3'],status=r'''Solved by the speaker: \citet[Lemma~1, Lemmas~2--3 and main theorem]{ryzhikova1987decidability}; received May 1986, Russian publication 1987, English translation 1988. As of November 2026, the exact identity-decision problem is settled; no complexity or general first-order decidability claim is added.''',status_date='2026-11',refs=['ryzhikova1987decidability']),
 dict(id='GP-1985-21',title='Index formulas for elliptic Fuchs-type operators with conic ends',
 statement=r'''For a cone-elliptic regular singular differential operator on a compact manifold with isolated conic ends, and a specified closed \(L^2\) domain between its minimal and maximal domains, express its index by interior data, Mellin-symbol spectral data, and the chosen indicial-domain contribution. This is a reconstruction of the notebook's general ``index?'' question; its printed operator and domain are incomplete.''',
 occurrences=['1985-654.6'],status=r'''Developed by others. \citet[Prop.~1.3.16 and Cor.~2.4.7]{lesch1997fuchs} proves Fredholmness and an index formula in the constant-near-tip setting; Thm.~2.4.8 specializes it for first-order operators. Habilitation submitted 1993; preprint 1996; book 1997. As of November 2026 this is an established formulation, not a claim that every unqualified regular singular expression has a canonical index.''',status_date='2026-11',refs=['lesch1997fuchs']),
 dict(id='GP-1982-03',title='Reducibility and first singular vectors of Virasoro Verma modules',
 statement=r'''For \(h,c\in\mathbb C\), determine when the Virasoro Verma module \(M(h,c)\) is reducible and determine its first positive grade containing a singular vector. The central-generator convention must be fixed before comparing formulas.''',
 occurrences=['1982-566.7','1985-657.3','1985-657.4'],status=r'''Solved before the present talk. \citet[\S3.2, Thm.~3.1 and corollary]{feiginfuchs1982invariant} gives the determinant factors and the first-grade criterion. Received September 1981, published 1982. As of November 2026, this recurrence remains E; the 1985 notebook's \(1/2\) coefficient must be corrected to \(1/16\).''',status_date='2026-11',refs=['feiginfuchs1982invariant'])
]
(OUT/'problems.json').write_text(json.dumps(problems,ensure_ascii=False,indent=2)+'\n')

# Reuse cumulative keys, retaining canonical bibliographic fields while recording
# the exact scope of this run's verification in sources.json below.
old=(ROOT/'work/references_cumulative.bib').read_text()
entries={}
for m in re.finditer(r'@\w+\s*\{\s*([^,]+),',old):
    start=m.start();pos=m.end();depth=1
    while pos<len(old) and depth:
        if old[pos]=='{' and (pos==0 or old[pos-1]!='\\'): depth+=1
        if old[pos]=='}' and (pos==0 or old[pos-1]!='\\'): depth-=1
        pos+=1
    entries[m.group(1).strip()]=old[start:pos]
needed=sorted({k for i in items for k in i['refs']})
new={}
def bib(key,kind,**data):
    new[key]='@'+kind+'{'+key+',\n'+''.join('  '+k+' = {'+v+'},\n' for k,v in data.items())+'}'
