# CSV entries are authorial emendations where the same error is visible in the
# handwriting. They are not labelled OCR/transcription errors.
rows=[]
def correction(page,place,old,new,evidence,type='faithful_error',applies='both'):
    rows.append(dict(page=page,place=place,transcription_reads=old,should_read=new,evidence=evidence,applies_to=applies,type=type))
